import React, { useEffect, useState } from 'react';
import { chatWithBot, createChatSession, getChatMessages } from './api/apiClient';

const Chatbot = ({ applicantId, token, mode = 'applicant' }) => {
  const [question, setQuestion] = useState('');
  const [answer, setAnswer] = useState('');
  const [loading, setLoading] = useState(false);
  const [sessionId, setSessionId] = useState(null);
  const [history, setHistory] = useState([]); // {role:'user'|'assistant', text:string}

  // Load existing session for this mode (and applicant if applicable)
  useEffect(() => {
    const key = mode === 'applicant' && applicantId ? `chat_session_${mode}_${applicantId}` : `chat_session_${mode}`;
    const sid = window.localStorage.getItem(key);
    if (sid) {
      setSessionId(Number(sid));
      // hydrate messages
      getChatMessages(token, Number(sid))
        .then(res => {
          const msgs = res.data?.messages || [];
          setHistory(msgs.map(m => ({ role: m.role, text: m.text })));
        })
        .catch(() => {});
    }
  }, [mode, applicantId, token]);

  const ensureSession = async () => {
    if (sessionId) return sessionId;
    const res = await createChatSession(token, mode, applicantId ?? null);
    const newId = res.data?.session_id;
    if (newId) {
      setSessionId(newId);
      const key = mode === 'applicant' && applicantId ? `chat_session_${mode}_${applicantId}` : `chat_session_${mode}`;
      window.localStorage.setItem(key, String(newId));
    }
    return newId;
  };

  const handleAsk = async (e) => {
    e.preventDefault();
    setLoading(true);
    setAnswer('');
    try {
      const sidReady = await ensureSession();
      const res = await chatWithBot(question, applicantId, token, mode, sidReady);
      const sid = res.data.session_id || sessionId;
      if (sid && sid !== sessionId) {
        setSessionId(sid);
        const key = mode === 'applicant' && applicantId ? `chat_session_${mode}_${applicantId}` : `chat_session_${mode}`;
        window.localStorage.setItem(key, String(sid));
      }
      const ans = res.data.answer;
      setAnswer(ans);
      setHistory((h) => [...h, { role: 'user', text: question }, { role: 'assistant', text: ans }]);
    } catch {
      setAnswer('Error getting answer.');
    } finally {
      setLoading(false);
    }
  };

  const handleNewChat = async () => {
    setHistory([]);
    setAnswer('');
    setSessionId(null);
    const key = mode === 'applicant' && applicantId ? `chat_session_${mode}_${applicantId}` : `chat_session_${mode}`;
    window.localStorage.removeItem(key);
    try {
      const res = await createChatSession(token, mode, applicantId ?? null);
      const sid = res.data?.session_id;
      if (sid) {
        setSessionId(sid);
        window.localStorage.setItem(key, String(sid));
      }
    } catch {}
  };

  return (
    <div>
      <h2>{mode === 'corpus' ? 'Recruiter chat (all applicants)' : 'Chat'}</h2>
      <form onSubmit={handleAsk} className="toolbar">
        <input className="input" type="text" value={question} onChange={e => setQuestion(e.target.value)} placeholder="Ask a question…" required />
        <button className="btn" type="submit" disabled={loading}>{loading ? 'Asking…' : 'Ask'}</button>
        <button type="button" className="btn btn-secondary" onClick={handleNewChat} disabled={loading} style={{ marginLeft: 8 }}>New Chat</button>
      </form>
      {history.length > 0 && (
        <div className="card" style={{ maxHeight: 380, overflowY: 'auto', background:'#0b0f16' }}>
          {history.map((m, i) => (
            <div key={i} style={{ marginBottom: 10, display:'flex', justifyContent: m.role==='user'?'flex-end':'flex-start' }}>
              <div style={{
                maxWidth:'92%',
                whiteSpace:'pre-wrap',
                overflowWrap:'anywhere',
                background: m.role==='user' ? 'rgba(0,224,164,0.08)' : 'rgba(255,255,255,0.04)',
                border:'1px solid var(--border)',
                borderRadius: 12,
                padding:'8px 10px',
                color: 'var(--text)'
              }}>
                <div style={{ fontSize: '.8rem', color: 'var(--muted)', marginBottom:4 }}>{m.role==='user'?'You':'Assistant'}</div>
                {m.text}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Chatbot;
